package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	// Build dynamic query
	query := "SELECT id, name, price, description FROM products WHERE 1=1"

	if category != "" {
		// Using parameterized approach for category
		query += fmt.Sprintf(" AND category = '%s'", sanitizeCategory(category))
	}

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	if maxPrice != "" {
		query += fmt.Sprintf(" AND price <= %s", maxPrice)
	}

	// Sort handling
	if sortBy != "" {
		allowedSorts := map[string]bool{"price": true, "name": true, "id": true}
		if allowedSorts[sortBy] {
			query += " ORDER BY " + sortBy
		}
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
		first = false
	}
	w.Write([]byte("\n]"))
}

func sanitizeCategory(input string) string {
	// Basic sanitization - remove obvious SQL keywords
	dangerous := []string{"DROP", "DELETE", "INSERT", "UPDATE", "ALTER", "EXEC"}
	upper := strings.ToUpper(input)
	for _, kw := range dangerous {
		if strings.Contains(upper, kw) {
			return ""
		}
	}
	return strings.ReplaceAll(input, "'", "''")
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
